-- Only available first-party evidence is promoted. Gated requirements remain
-- needs_review; this migration never invents text/limits or backfills essays.
UPDATE college_prompt_sets SET coverage='verified',source_url='https://apply.commonapp.org/mycolleges/354/2786/8113',
 verified_on='2026-10-26',review_due_on='2027-08-01',
 notes='Fall-2027 Common App inspected October 26, 2026. The main Common App personal essay is required and is not duplicated here. No general additional Academics essay appeared for Arts and Sciences, Engineering, Architecture or Kinesiology. Nursing applicants have one required conditional response: aim for about 250 words; the application accepts at most 300. Specialized routes, disclosures and scholarships still need individual review.'
WHERE firm_id IS NULL AND scorecard_id=234076 AND entry_year=2027;
INSERT INTO college_library_prompts(prompt_set_id,prompt_key,title,prompt_text,word_limit,requirement,text_kind,sort_order)
SELECT id,'nursing','University of Virginia — Nursing experience',
 'For School of Nursing applicants only: describe a health-care experience or significant interaction that strengthened your interest in nursing. Suggested length: about 250 words. The application permits 1–300 words.',300,'conditional','summary',0
FROM college_prompt_sets WHERE firm_id IS NULL AND scorecard_id=234076 AND entry_year=2027
ON CONFLICT(prompt_set_id,prompt_key) DO NOTHING;

